private TreeNode<T> rotateRight(TreeNode<T> node){
    TreeNode<T> leftChild = node.getLeft();
    node.setLeft(leftChild.getRight());
    leftChild.setRight(node);
    return leftChild;
}

public TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node.left == null) {
        return node;
    }

    TreeNode<T> left = node.left;
    node.left = left.right;
    left.right = node;

    return left;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    TreeNode<T> newParent = node.getRightChild();
    node.setRightChild(newParent.getLeftChild());
    newParent.setLeftChild(node);
    return newParent;
}

public TreeNode<T> rotateRight(TreeNode<T> node){

        // create a new parent for the node
        TreeNode<T> parent = new TreeNode<>();

        // left child of the new parent
        parent.left = node;
        // right child of the new parent
        parent.right = node.left;

        // adjust the node and its left child
        node.left = null;
        node.updateHeight();
        parent.updateHeight();

        return parent;
}

