    // Generate a complete bipartite graph
    List<V> vertices1 = new ArrayList<>();
    List<V> vertices2 = new ArrayList<>();

    // Add vertices to the two partitions
    for (String id : resultMap.keySet()) {
        V vertex = resultMap.get(id);
        if (vertex.getPartition() == 1) {
            vertices1.add(vertex);
