    }
    int count = bounds.size();
    List<Integer> suffixSums = new ArrayList<>(count);
    long sum = 0;

    // Step 2: Compute suffix sum
    for (int i = 0; i < count; i++) {
        Integer bound = bounds.get(i);
        if (bound == null) {
