public static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {

    // Check if the graph and vertices are not null
    if (graph == null || vertices == null) {
        return false;
    }

    // Check if the number of vertices is at least 2
    if (vertices.size() < 2) {
        return false;
    }

    // Check if all vertices are connected
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!graph.hasEdge(v1, v2)) {
                return false;
            }
        }
    }

    return true;
}

boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (graph.hasEdge(vertex1, vertex2)) {
                continue;
            } else {
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    Queue<V> queue = new LinkedList<>();
    Set<V> visited = new HashSet<>();
    visited.addAll(vertices);
    queue.offer(vertices.iterator().next());
    while (!queue.isEmpty()) {
        V vertex = queue.poll();
        if (!visited.contains(vertex)) {
            visited.add(vertex);
            queue.offer(vertex);
        }
        for (V neighbor : graph.getNeighbors(vertex)) {
            if (!visited.contains(neighbor)) {
                queue.offer(neighbor);
            }
        }
    }
    return visited.size() == vertices.size();
}

