public void abbreviate(final int nameStart, final StringBuffer buf) {
    // if the name starts with a space, it's an abbreviation, so return the original name
    if (nameStart < 1) {
        return;
    }

    // get the first character of the name
    char firstChar = buf.charAt(nameStart);

    // if the first character is a letter, append it to the buffer
    if (Character.isLetter(firstChar)) {
        buf.append(firstChar);
    }

    // if the first character is a digit, append a space followed by the digit
    else if (Character.isDigit(firstChar)) {
        buf.append(' ');
        buf.append(firstChar);
    }

    // if the first character is a symbol, append a space followed by the symbol
    else if (Character.isSymbol(firstChar)) {
        buf.append(' ');
        buf.append(firstChar);
    }

    // if the first character is a whitespace, append a space
    else if (Character.isWhitespace(firstChar)) {
        buf.append(' ');
    }

    // if the first character is a punctuation, append a space followed by the punctuation
    else if (Character.isPunctuation(firstChar)) {
        buf.append(' ');
        buf.append(firstChar);
    }

    // if the first character is a currency symbol, append a space followed by the currency symbol
    else if (Character.isCurrencySymbol(firstChar)) {
        buf.append(' ');
        buf.append(firstChar);
    }

    // if the first character is a modifier symbol, append a space followed by the modifier symbol
    else if (Character.isModifierSymbol(firstChar)) {
        buf.append(' ');
        buf.append(firstChar);
    }

    // if the first character is a other symbol, append a space followed by the other symbol
    else if (Character.isOtherSymbol(firstChar)) {
