    int day = time.getDayOfWeek().getValue();

    // Calculate the step value
    int stepValue = dayStep - day;

    // Adjust the time bucket based on the step value
    long newTimeBucket = timeBucket - stepValue * 86400;

    // Return the new time bucket
    return newTimeBucket;
}

